func (this *Deepcoin) ParseTransaction(transaction any, optionalArgs ...any) Transaction {
	//
	// fetchDeposits
	//     {
	//         "createTime": 1760368656,
	//         "txHash": "03fe3244d89e794586222413c61779380da9e9fe5baaa253c38d01a4199a3499",
	//         "chainName": "TRC20",
	//         "amount": "149",
	//         "coin": "USDT",
	//         "status": "succeed"
	//     }
	//
	var currency map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = currency
	var txid *string = this.SafeString(transaction, "txHash")
	var currencyId *string = this.SafeString(transaction, "coin")
	var code *string = this.SafeCurrencyCode(currencyId, currency)
	var amount *float64 = this.SafeNumber(transaction, "amount")
	var timestamp *int64 = this.SafeTimestamp(transaction, "createTime")
	var networkId *string = this.SafeString(transaction, "chainName")
	var network *string = this.NetworkIdToCode(networkId, code)
	var status *string = this.ParseTransactionStatus(this.SafeString(transaction, "status"))
	return TransactionFromMap(map[string]any{
		"info":        transaction,
		"id":          nil,
		"currency":    code,
		"amount":      amount,
		"network":     network,
		"addressFrom": nil,
		"addressTo":   nil,
		"address":     this.SafeString(transaction, "address"),
		"tagFrom":     nil,
		"tagTo":       nil,
		"tag":         nil,
		"status":      status,
		"type":        nil,
		"updated":     nil,
		"txid":        txid,
		"timestamp":   timestamp,
		"datetime":    this.Iso8601(timestamp),
		"internal":    nil,
		"comment":     nil,
		"fee": map[string]any{
			"currency": nil,
			"cost":     nil,
		},
	})
}
func (this *Deepcoin) ParseTransactionStatus(status *string) *string {
	var statuses map[string]any = map[string]any{
		"confirming": "pending",
		"succeed":    "ok",
	}
	return this.SafeString(statuses, status, status)
}

